type Term = Num int | Add Term Term | Mul Term Term | Neg Term | Var string
let vars = Map.ofList [("x", 6), ("y", 9)]
let calc e =
  match e:
    case Num n: n
    case Add a b: calc a + calc b
    case Mul a b: calc a * calc b
    case Neg a: -(calc a)
    case Var v: Map.findOr v 0 vars
let render e =
  match e:
    case Num n if n < 0: f"({n})"
    case Num n: f"{n}"
    case Add a b: f"({render a} + {render b})"
    case Mul a b: f"{render a} * {render b}"
    case Neg a: f"-{render a}"
    case Var v: v
let terms = [(Mul (Var "x") (Neg (Neg (Num 1)))), (Mul (Var "x") (Neg (Var "y"))), (Add (Mul (Var "x") (Add (Num 5) (Num (-2)))) (Num 5))]
