let (|Low|Mid|High|) n =
  let scaled = n * 2
  if scaled < 4 then Low
  else if scaled < 24 then Mid
  else High
let (|KeyVal|_|) s =
  match String.split "=" s:
    case [k, v]:
      match String.toInt v:
        case Some n: Some (String.strip k, n)
        case None: None
    case _: None
let tier n =
  match n:
    case Low: "low"
    case Mid: "mid"
    case High: "high"
let label s =
  match s:
    case KeyVal pair if snd pair < 0: f"{fst pair}: negative"
    case KeyVal pair: f"{fst pair}: {tier (snd pair)}"
    case _: "?"
