type Change = Put string int | Append int | Skip
let step acc op =
  match acc:
    case (m, xs):
      match op:
        case Put k v: (Map.add k v m, xs)
        case Append n: (m, List.concat xs [n])
        case Skip: acc
let runAll script = List.fold step (Map.empty, []) script
let script = [Append 6, Skip, Skip, Append 7, Append 1, Skip]
let final = runAll script
let (mm, items) = final
print (Map.toList mm, items)

