let boxes = [Box { w = 8, h = 3, label = "pin" }, Box { w = 2, h = 4, label = "cog" }, Box { w = 6, h = 1, label = "cog" }, Box { w = 1, h = 3, label = "rod" }, Box { w = 4, h = 4, label = "sq" }]
let describe b =
  match b:
    case Box { w, h, label } if w == h: f"{label} square {w}"
    case Box { label, w = 1 }: f"{label} thin"
    case Box { label, w }: f"{label} wide {w}"
print (boxes |> List.map describe |> String.join "; ")
print (boxes |> List.filter (fun (Box { w, h }) -> w > h) |> List.map (fun (Box { label }) -> label))
let relabel prefix b =
  let Box { label } = b
  { b with label = String.concat prefix label }
print (List.map (relabel "new ") boxes |> List.head)
